#!/bin/bash
set -euo pipefail

# CI-only image creation for the already signed and verified 0.3.13 app.
# The caller runs this script inside the disposable offline sandbox. This is
# intentionally separate from the normal macOS installer script.
if test "$#" != 2; then
  echo 'Expected app and image paths.' >&2; exit 2
fi
test "${CI:-}" = true
test "${GITHUB_ACTIONS:-}" = true
test "${RUNNER_ENVIRONMENT:-}" = github-hosted
test "${RUNNER_OS:-}" = macOS
test "${AITM_MACOS_TEST_SANDBOX:-}" = 1
test "${AITM_SYNTHETIC_REQUIRED:-}" = 1
test -z "${HOME+x}"
test -z "${CODEX_HOME+x}"
test -n "${AITM_CI_DENIED_FILE:-}"
if /bin/cat "$AITM_CI_DENIED_FILE" >/dev/null 2>&1; then
  echo 'The runner-profile read guard is not active.' >&2; exit 1
fi
task_root="${AITM_RELEASE_ROOT:?}"
case "$task_root" in /Users/runner/work/_temp/aitm-card-tests.*) ;; *) echo 'Unexpected task root.' >&2; exit 1;; esac
test "${AITM_SYNTHETIC_TEST_ROOT:-}" = "$task_root/temp"
test -d "$task_root" && test ! -L "$task_root"
test "$(cd -P "$task_root" && pwd -P)" = "$task_root"
test -d "$task_root/temp" && test ! -L "$task_root/temp"
test "$(cd -P "$task_root/temp" && pwd -P)" = "$task_root/temp"
task_source="$task_root/source/macos"
task_app="$task_source/dist/AI Task Monitor.app"
task_output="$task_source/dist/AITaskMonitor-macOS-0.3.13.dmg"
if test "$1" != "$task_app" || test "$2" != "$task_output"; then
  echo 'Unexpected app or image path.' >&2; exit 2
fi
test -d "$task_source/dist" && test ! -L "$task_source/dist"
test "$(cd -P "$task_source/dist" && pwd -P)" = "$task_source/dist"
test -d "$task_app" && test ! -L "$task_app"
test ! -e "$task_output" && test ! -L "$task_output"
test ! -e "$task_source/dist/SHA256SUMS-macOS.txt" && test ! -L "$task_source/dist/SHA256SUMS-macOS.txt"
task_special="$(/usr/bin/find -P "$task_app" ! -type f ! -type d -print -quit)"
test -z "$task_special"
/usr/bin/codesign --verify --deep --strict --verbose=2 "$task_app"

task_work="$(/usr/bin/mktemp -d "$task_root/temp/aitm-hybrid.XXXXXXXX")"
case "$task_work" in "$task_root"/temp/aitm-hybrid.*) ;; *) exit 1;; esac
test -d "$task_work" && test ! -L "$task_work"
test "$(cd -P "$task_work" && pwd -P)" = "$task_work"
/bin/mkdir "$task_work/stage" "$task_work/rw-mount" "$task_work/ro-mount"
/usr/bin/ditto "$task_app" "$task_work/stage/AI Task Monitor.app"
/usr/bin/codesign --verify --deep --strict --verbose=2 "$task_work/stage/AI Task Monitor.app"
/bin/ln -s /Applications "$task_work/stage/Applications"
# makehybrid creates a full volume. Reserve blocks so its metadata can be
# repaired after conversion to a writable temporary image.
/bin/dd if=/dev/zero of="$task_work/stage/.aitm-padding" bs=1048576 count=16
test "$(/usr/bin/stat -f %z "$task_work/stage/.aitm-padding")" = 16777216
/usr/bin/hdiutil makehybrid -hfs -hfs-volume-name 'AI Task Monitor' \
  -o "$task_work/hybrid.dmg" "$task_work/stage"
/usr/bin/hdiutil convert "$task_work/hybrid.dmg" -format UDRW -o "$task_work/hybrid-rw.dmg"
test -s "$task_work/hybrid-rw.dmg"

task_mounted=''
cleanup_mount() {
  if test -n "$task_mounted"; then
    /usr/bin/hdiutil detach "$task_mounted" >/dev/null 2>&1 || true
  fi
}
trap cleanup_mount EXIT
check_mount() {
  local task_plist="$1" task_expected="$2" task_index task_value task_found=0
  for task_index in {0..15}; do
    task_value="$(/usr/libexec/PlistBuddy -c "Print :system-entities:$task_index:mount-point" "$task_plist" 2>/dev/null || true)"
    if test "$task_value" = "$task_expected"; then
      test "$(/usr/libexec/PlistBuddy -c "Print :system-entities:$task_index:volume-kind" "$task_plist")" = hfs
      task_found=$((task_found + 1))
    fi
  done
  test "$task_found" = 1
  test -d "$task_expected/AI Task Monitor.app"
  test ! -L "$task_expected/AI Task Monitor.app"
  test -L "$task_expected/Applications"
  test "$(/usr/bin/readlink "$task_expected/Applications")" = /Applications
}
task_rw="$task_work/rw-mount"
task_mounted="$task_rw"
/usr/bin/hdiutil attach -plist -readwrite -nobrowse -noautoopen \
  -mountpoint "$task_rw" "$task_work/hybrid-rw.dmg" > "$task_work/attach-rw.plist"
check_mount "$task_work/attach-rw.plist" "$task_rw"
task_rw_app="$task_rw/AI Task Monitor.app"
task_special="$(/usr/bin/find -P "$task_rw_app" ! -type f ! -type d -print -quit)"
test -z "$task_special"
test -f "$task_rw/.aitm-padding" && test ! -L "$task_rw/.aitm-padding"
test "$(/usr/bin/stat -f %z "$task_rw/.aitm-padding")" = 16777216
/bin/sh -c ': > "$1"' sh "$task_rw/.aitm-padding"
test "$(/usr/bin/stat -f %z "$task_rw/.aitm-padding")" = 0
task_free="$(/bin/df -Pk "$task_rw" | /usr/bin/awk 'END {print $4}')"
[[ "$task_free" =~ ^[0-9]+$ ]]
test "$task_free" -ge 1024

# This documented marker applies only to the temporary image. Refuse any
# pre-existing event files rather than removing data generated by the OS.
task_events="$task_rw/.fseventsd"
if test -e "$task_events" || test -L "$task_events"; then
  test -d "$task_events" && test ! -L "$task_events"
  task_existing="$(/usr/bin/find -P "$task_events" -xdev -mindepth 1 -maxdepth 1 -print -quit)"
  test -z "$task_existing"
else
  /bin/mkdir "$task_events"
fi
task_device="$(/usr/bin/stat -f %d "$task_rw")"
test "$(/usr/bin/stat -f %d "$task_events")" = "$task_device"
test ! -L "$task_events/no_log"
/usr/bin/touch "$task_events/no_log"
test "$(/usr/bin/stat -f %z "$task_events/no_log")" = 0
test "$(/usr/bin/stat -f %d "$task_events/no_log")" = "$task_device"
/bin/rm "$task_rw/.aitm-padding"
test ! -e "$task_rw/.aitm-padding"

# HFS hybrid creation may add FinderInfo that makes an otherwise intact signed
# app fail strict validation. Remove only that attribute, only inside the
# checked image, then require strict signatures and exact file contents.
/usr/bin/find -P "$task_rw_app" -xdev \( -type f -o -type d \) -print0 > "$task_work/app-entries"
while IFS= read -r -d '' task_entry; do
  case "$task_entry" in "$task_rw_app"|"$task_rw_app"/*) ;; *) exit 1;; esac
  test ! -L "$task_entry"
  test "$(/usr/bin/stat -f %d "$task_entry")" = "$task_device"
  task_attributes="$(/usr/bin/xattr "$task_entry")"
  if printf '%s\n' "$task_attributes" | /usr/bin/grep -Fx 'com.apple.FinderInfo' >/dev/null; then
    /usr/bin/xattr -d com.apple.FinderInfo "$task_entry"
  fi
done < "$task_work/app-entries"
/usr/bin/diff -qr "$task_app" "$task_rw_app"
/usr/bin/codesign --verify --deep --strict --verbose=2 "$task_rw_app"
test -d "$task_events" && test ! -L "$task_events"
test -f "$task_events/no_log" && test ! -L "$task_events/no_log"
test "$(/usr/bin/stat -f %z "$task_events/no_log")" = 0
task_event_paths="$(/usr/bin/find -P "$task_events" -xdev -mindepth 1 -maxdepth 1 -print)"
test "$task_event_paths" = "$task_events/no_log"
task_entry_count="$(/usr/bin/find -P "$task_rw" -mindepth 1 -maxdepth 1 -print | /usr/bin/wc -l | /usr/bin/tr -d ' ')"
test "$task_entry_count" = 3
/usr/bin/hdiutil detach "$task_rw"
task_mounted=''

/usr/bin/hdiutil convert "$task_work/hybrid-rw.dmg" -format UDZO -o "$task_work/final.dmg"
test -s "$task_work/final.dmg"
/usr/bin/hdiutil verify "$task_work/final.dmg"
task_ro="$task_work/ro-mount"
task_mounted="$task_ro"
/usr/bin/hdiutil attach -plist -readonly -nobrowse -noautoopen \
  -mountpoint "$task_ro" "$task_work/final.dmg" > "$task_work/attach-ro.plist"
check_mount "$task_work/attach-ro.plist" "$task_ro"
task_ro_app="$task_ro/AI Task Monitor.app"
task_entry_count="$(/usr/bin/find -P "$task_ro" -mindepth 1 -maxdepth 1 -print | /usr/bin/wc -l | /usr/bin/tr -d ' ')"
test "$task_entry_count" = 3
test -d "$task_ro/.fseventsd" && test ! -L "$task_ro/.fseventsd"
test -f "$task_ro/.fseventsd/no_log" && test ! -L "$task_ro/.fseventsd/no_log"
test "$(/usr/bin/stat -f %z "$task_ro/.fseventsd/no_log")" = 0
task_event_paths="$(/usr/bin/find -P "$task_ro/.fseventsd" -xdev -mindepth 1 -maxdepth 1 -print)"
test "$task_event_paths" = "$task_ro/.fseventsd/no_log"
task_ro_device="$(/usr/bin/stat -f %d "$task_ro")"
test "$(/usr/bin/stat -f %d "$task_ro/.fseventsd")" = "$task_ro_device"
test "$(/usr/bin/stat -f %d "$task_ro/.fseventsd/no_log")" = "$task_ro_device"
test -x "$task_ro_app/Contents/MacOS/AITaskMonitor"
/usr/bin/cmp "$task_app/Contents/MacOS/AITaskMonitor" "$task_ro_app/Contents/MacOS/AITaskMonitor"
/usr/bin/cmp "$task_app/Contents/Resources/AppIcon.icns" "$task_ro_app/Contents/Resources/AppIcon.icns"
if test -f "$task_root/release-artifacts/icon-fallback-used"; then
  test ! -L "$task_root/release-artifacts/icon-fallback-used"
  task_icon_sha='ec9ba4d716b1988dfad213127d9d2dffbb37e188199f8c7576d4325774e78e67'
  test "$(cat "$task_root/release-artifacts/icon-fallback-used")" = "$task_icon_sha"
  task_icon_actual="$(/usr/bin/shasum -a 256 "$task_ro_app/Contents/Resources/AppIcon.icns")"
  test "${task_icon_actual%% *}" = "$task_icon_sha"
fi
/usr/bin/diff -qr "$task_app" "$task_ro_app"
/usr/bin/codesign --verify --deep --strict --verbose=2 "$task_ro_app"
/bin/bash "$task_source/scripts/smoke-test.sh" "$task_ro_app"
/usr/bin/ditto "$task_ro_app" "$task_work/copied.app"
/usr/bin/codesign --verify --deep --strict --verbose=2 "$task_work/copied.app"
/usr/bin/diff -qr "$task_app" "$task_work/copied.app"
/bin/bash "$task_source/scripts/smoke-test.sh" "$task_work/copied.app"
/usr/bin/hdiutil detach "$task_ro"
task_mounted=''
trap - EXIT

# Install the result into the CI artifact directory only after every check.
/bin/cp "$task_work/final.dmg" "$task_output"
/usr/bin/cmp "$task_work/final.dmg" "$task_output"
(cd "$task_source/dist" && /usr/bin/shasum -a 256 "$(/usr/bin/basename "$task_output")" > SHA256SUMS-macOS.txt && /usr/bin/shasum -a 256 -c SHA256SUMS-macOS.txt)
printf '%s\n' 'CI-only makehybrid HFS image, converted to writable for FinderInfo cleanup and then UDZO.' \
  'Contains only the app, the Applications link and an empty .fseventsd/no_log marker.' \
  'Image and copied app passed strict signature, content and smoke checks in the offline sandbox.' \
  > "$task_root/release-artifacts/image-method.txt"
